   public static void extend(Map<KnockerBrain.Intent, String[][]> lines) {
      for(Map.Entry<KnockerBrain.Intent, String[][]> e : EXTRA.entrySet()) {
         String[][] base = (String[][])lines.get(e.getKey());
         if (base == null) {
            lines.put((KnockerBrain.Intent)e.getKey(), (String[][])e.getValue());
         } else {
            String[][] merged = new String[base.length][];

            for(int p = 0; p < base.length; ++p) {
               String[] add = p < ((String[][])e.getValue()).length ? ((String[][])e.getValue())[p] : new String[0];
               String[] b = base[p] == null ? new String[0] : base[p];
               merged[p] = concat(b, add);
            }

            lines.put((KnockerBrain.Intent)e.getKey(), merged);
         }
      }

   }

   public static String[] concat(String[] a, String[] b) {
      String[] r = new String[a.length + b.length];
      System.arraycopy(a, 0, r, 0, a.length);
      System.arraycopy(b, 0, r, a.length, b.length);
      return r;
   }

